;(function renderLooxRatings() {
  function update() {
    document.querySelectorAll('.loox-rating').forEach(function(el) {
      if (el.querySelector('.loox-rating-content')) return;
      var rating = el.getAttribute('data-rating') || '4.9';
      var raters = el.getAttribute('data-raters') || '831';
      var starSvg = '<svg class="loox-icon" viewBox="0 0 24 24" style="width:14px;height:14px;fill:#e5a800;display:inline-block;vertical-align:middle;margin-right:2px;"><path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg>';
      el.innerHTML = '<div class="loox-rating-content" style="display:inline-flex;align-items:center;font-size:13px;font-weight:500;color:#000;">' +
        starSvg.repeat(5) +
        '<span style="margin-left:4px;">' + rating + ' | ' + raters + ' avaliações</span></div>';
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', update);
  } else {
    update();
  }
  setTimeout(update, 300);
  setTimeout(update, 1000);
})();
